<script setup lang="ts">
import {computed,ref,onMounted,onUnmounted} from 'vue';import {useCoffee} from '../stores/coffee';import {localTime,stateLabels} from '../../../../packages/shared/src/domain';import type {Order} from '../../../../packages/shared/src/types';import Icon from '../components/Icon.vue';
const s=useCoffee();const station=ref('all');const clock=ref(Date.now());let timer:ReturnType<typeof setInterval>;onMounted(()=>timer=setInterval(()=>clock.value=Date.now(),15000));onUnmounted(()=>clearInterval(timer));
const columns=[{state:'accepted',title:'Chờ pha chế',next:'preparing',action:'Bắt đầu làm'},{state:'preparing',title:'Đang pha chế',next:'ready',action:'Hoàn tất món'},{state:'ready',title:'Sẵn sàng',next:'served',action:'Đã giao phục vụ'}];
const orders=computed(()=>s.orders.filter(o=>['accepted','preparing','ready'].includes(o.state)&&o.lines.some(l=>station.value==='all'||s.state.products.find(p=>p.id===l.productId)?.category===station.value)));
const age=(o:Order)=>Math.max(0,Math.floor((clock.value-new Date(o.createdAt).getTime())/60000));
function advance(o:Order,next:string){s.run(()=>s.repo.transition(o.id,next as Order['state']))}
</script><template><div class="page kds-page"><div class="page-heading"><div><h2>Quầy pha chế</h2><p>Ưu tiên món đang chờ, giữ rõ ghi chú cho từng đơn.</p></div><div class="filters"><select aria-label="Khu vực pha chế" v-model="station"><option value="all">Tất cả quầy</option><option value="coffee">Quầy cà phê</option><option value="tea">Quầy trà</option><option value="blend">Quầy matcha</option></select><span class="live-indicator"><i></i>{{orders.length}} đơn đang xử lý</span></div></div><div class="kds-grid"><section v-for="col in columns" :key="col.state" class="kds-column" :class="col.state"><header><h3><i></i>{{col.title}}</h3><span>{{orders.filter(o=>o.state===col.state).length}}</span></header><article v-for="o in orders.filter(o=>o.state===col.state)" :key="o.id" class="kds-ticket" :class="{overdue:age(o)>=10}"><header><strong>{{o.tableName}}</strong><span class="ticket-age"><Icon name="clock" :size="15"/>{{age(o)}} phút</span></header><div class="ticket-meta">{{o.number}}<span>{{localTime(o.createdAt)}}</span></div><div v-for="l in o.lines.filter(l=>station==='all'||s.state.products.find(p=>p.id===l.productId)?.category===station)" :key="l.id" class="kds-item"><b>{{l.quantity}}</b><div><strong>{{l.name}}</strong><small>{{({queued:"Chờ pha chế",preparing:"Đang làm",ready:"Sẵn sàng",served:"Đã giao"} as Record<string,string>)[o.itemStates?.[l.id]??(o.state==="accepted"?"queued":o.state)]}} · Size {{l.variant}} {{l.optionNames.length?'· '+l.optionNames.join(', '):''}}</small><p v-if="l.note">{{l.note}}</p><button class="text-link" v-if="(o.itemStates?.[l.id]??o.state)!=='served'" @click="s.run(()=>s.repo.transitionItem(o.id,l.id,({queued:'preparing',accepted:'preparing',preparing:'ready',ready:'served'} as Record<string,string>)[o.itemStates?.[l.id]??o.state]))">Cập nhật riêng món</button></div></div><p v-if="age(o)>=10" class="overdue-label">Đơn đang chờ lâu</p><button class="btn full" :class="col.state==='preparing'?'primary':'outline'" @click="advance(o,col.next)">{{col.action}}<Icon name="next" :size="16"/></button></article><div v-if="!orders.some(o=>o.state===col.state)" class="empty"><Icon name="coffee" :size="30"/><p>Không có đơn {{col.title.toLowerCase()}}</p></div></section></div><p class="muted small-copy">Cập nhật trong trình duyệt này. Đồng bộ giữa thiết bị sẽ được nối khi triển khai API.</p></div></template>
